package com.btsou.search;
import org.json.*;
import java.util.*;
import java.nio.file.*;
public final class SourceCatalogTests {
    static int checks;
    static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    static void reject(String raw,String why)throws Exception{try{new SourceCatalog(raw);}catch(Exception expected){checks++;return;}throw new AssertionError(why);}
    public static void run(String catalog,String fixtures)throws Exception{
        SourceCatalog base=new SourceCatalog(catalog);check(base.sources.size()==37&&base.ordinaryEnabled()==9,"active versus historical sources");
        check(SourceCatalog.choose(catalog,"broken").version==base.version,"corrupt cache falls back");
        String newer=new JSONObject(catalog).put("version",base.version+1).toString();check(SourceCatalog.choose(catalog,newer).version==base.version+1,"new cache selected");String older=new JSONObject(catalog).put("version",base.version-1).toString();check(SourceCatalog.choose(catalog,older).version==base.version,"cache cannot downgrade bundled");
        SourceCatalog.Update downloaded=SourceCatalog.download(base,url->newer);check(downloaded.changed&&downloaded.catalog.version==base.version+1,"valid update");
        final int[] attempts={0};SourceCatalog.Update fallback=SourceCatalog.download(base,url->{attempts[0]++;if(url.equals(SourceCatalog.PRIMARY))return "<html>error</html>";return newer;});check(fallback.changed&&attempts[0]==2,"bad primary uses official fallback");
        check(!SourceCatalog.download(base,url->catalog).changed,"same version unchanged");String altered=new JSONObject(catalog).put("updated","changed-without-version").toString();check(SourceCatalog.download(base,url->altered).catalog.raw.equals(catalog),"same version cannot silently replace endpoints");
        boolean failed=false;try{SourceCatalog.download(base,url->older);}catch(Exception e){failed=true;}check(failed&&base.raw.equals(catalog),"downgrade leaves current intact");
        failed=false;try{SourceCatalog.download(base,url->{throw new Exception("offline");});}catch(Exception e){failed=true;}check(failed&&base.sources.size()==37,"offline leaves known good intact");
        reject(new JSONObject(catalog).put("engine",99).toString(),"unsupported engine");reject(new JSONObject(catalog).put("schema",99).toString(),"unsupported schema");reject(new JSONObject(catalog).put("version",0).toString(),"invalid version");reject(new JSONObject(catalog).put("sources",new JSONArray()).toString(),"empty catalog");
        char[] huge=new char[SourceCatalog.MAX_BYTES+1];Arrays.fill(huge,' ');reject(new String(huge),"oversize catalog");JSONObject bad=new JSONObject(catalog);bad.getJSONArray("sources").getJSONObject(0).put("parser","downloaded-script");reject(bad.toString(),"no executable parser");bad=new JSONObject(catalog);bad.getJSONArray("sources").getJSONObject(0).put("charset","Utf8-16");reject(bad.toString(),"bad charset");bad=new JSONObject(catalog);bad.getJSONArray("sources").put(bad.getJSONArray("sources").getJSONObject(0));reject(bad.toString(),"duplicate source ID");
        Map<String,Source> by=new HashMap<>();for(Source s:base.sources)by.put(s.id,s);
        List<Result> first=SearchEngine.parse(by.get("bitsearch"),fixture(fixtures,"bitsearch.txt"),"https://bitsearch.eu/search?q=ubuntu&page=1");List<Result> second=SearchEngine.parse(by.get("bitsearch"),fixture(fixtures,"bitsearch_page2.txt"),"https://bitsearch.eu/search?q=ubuntu&page=2");check(first.size()==20,"bitsearch actual 20 magnets");check(second.size()==20,"bitsearch second page");Set<String> keys=new HashSet<>();for(Result r:first){check(r.url.startsWith("magnet:")&&Result.safeUrl(r.url),"direct valid magnet");keys.add(r.key());}check(second.stream().anyMatch(r->!keys.contains(r.key())),"real distinct pages");check(SearchEngine.parse(by.get("bitsearch"),fixture(fixtures,"bitsearch_empty.txt"),"https://bitsearch.eu/search?q=random").isEmpty(),"empty query not treated as popular results");
        List<Result> pans=SearchEngine.parse(by.get("pansou_public"),fixture(fixtures,"pansou_python.txt"),"https://so.252035.xyz/api/search?kw=python");check(pans.size()>=100,"public aggregation actual links");Set<String> kinds=new HashSet<>();for(Result r:pans)kinds.add(r.kind);check(kinds.containsAll(Arrays.asList("阿里","夸克","百度","迅雷")),"multi-cloud aggregate");check(pans.stream().anyMatch(r->!r.password.isEmpty()),"aggregate preserves known passwords");check(SearchEngine.parse(by.get("pansou_public"),fixture(fixtures,"pansou_empty_retry.txt"),"https://so.252035.xyz/api/search?kw=random").isEmpty(),"aggregate empty result");
        List<Result> aip=SearchEngine.parse(by.get("aipan"),fixture(fixtures,"aipan_details.json"),"https://www.aipan.me/");check(!aip.isEmpty(),"aipan actual links");check(aip.stream().anyMatch(r->r.url.startsWith("magnet:")),"aipan magnet links");check(aip.stream().anyMatch(r->!r.kind.equals("bt")),"aipan cloud links");check(by.get("aipan").url("蜘蛛侠",2).endsWith("%E8%9C%98%E8%9B%9B%E4%BE%A0"),"aipan query not corrupted by page");
        System.out.println("SOURCE_CATALOG_TESTS_OK checks="+checks+" bitsearch="+first.size()+" aggregation="+pans.size()+" aipan="+aip.size());
    }
    private static String fixture(String root,String name)throws Exception{if(root==null){try(java.io.InputStream in=SourceCatalogTests.class.getResourceAsStream("/fixtures/"+name)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}}return new String(Files.readAllBytes(Paths.get(root,name)),"UTF-8");}
    public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);run(new String(Files.readAllBytes(root.resolve("android/app/src/main/assets/sources.json")),"UTF-8"),root.resolve("research/probes").toString());}
}
